package main

import (
	"fmt"
	"os"
	"syscall"
	"time"
	"unsafe"
)

type terminal struct {
	file *os.File
	orig syscall.Termios
	raw  bool
}

func newTerminal(file *os.File) (*terminal, error) {
	var state syscall.Termios
	if err := ioctlGetTermios(int(file.Fd()), &state); err != nil {
		return nil, err
	}
	return &terminal{file: file, orig: state}, nil
}

func (t *terminal) enableRaw() error {
	if t.raw {
		return nil
	}
	state := t.orig
	state.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	state.Oflag &^= syscall.OPOST
	state.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	state.Cflag &^= syscall.CSIZE | syscall.PARENB
	state.Cflag |= syscall.CS8
	state.Cc[syscall.VMIN] = 1
	state.Cc[syscall.VTIME] = 0
	if err := ioctlSetTermios(int(t.file.Fd()), &state); err != nil {
		return err
	}
	t.raw = true
	return nil
}

func (t *terminal) disableRaw() error {
	if !t.raw {
		return nil
	}
	if err := ioctlSetTermios(int(t.file.Fd()), &t.orig); err != nil {
		return err
	}
	t.raw = false
	return nil
}

func terminalSize(file *os.File) (rows, cols int) {
	ws := &syscall.Winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, file.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if errno != 0 || ws.Col == 0 || ws.Row == 0 {
		return 24, 80
	}
	return int(ws.Row), int(ws.Col)
}

func ioctlGetTermios(fd int, state *syscall.Termios) error {
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(state)), 0, 0, 0)
	if errno != 0 {
		return errno
	}
	return nil
}

func ioctlSetTermios(fd int, state *syscall.Termios) error {
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(state)), 0, 0, 0)
	if errno != 0 {
		return errno
	}
	return nil
}

func waitReadable(fd int, timeout time.Duration) bool {
	var set syscall.FdSet
	set.Bits[fd/64] |= 1 << (uint(fd) % 64)
	tv := syscall.NsecToTimeval(timeout.Nanoseconds())
	n, err := syscall.Select(fd+1, &set, nil, nil, &tv)
	return err == nil && n > 0
}

type keyKind int

const (
	keyUnknown keyKind = iota
	keyRune
	keyUp
	keyDown
	keyLeft
	keyRight
	keyShiftUp
	keyShiftDown
	keyEnter
	keyBackspace
	keyDelete
	keyEscape
	keyCtrlC
)

type keyEvent struct {
	kind keyKind
	r    rune
}

func readKey(file *os.File) (keyEvent, error) {
	buf := make([]byte, 1)
	n, err := file.Read(buf)
	if err != nil {
		return keyEvent{}, err
	}
	if n == 0 {
		return keyEvent{}, fmt.Errorf("short read")
	}
	b := buf[0]
	switch b {
	case 3:
		return keyEvent{kind: keyCtrlC}, nil
	case '\r', '\n':
		return keyEvent{kind: keyEnter}, nil
	case 127:
		return keyEvent{kind: keyBackspace}, nil
	case 27:
		return readEscapeSequence(file)
	default:
		if b >= 32 && b <= 126 {
			return keyEvent{kind: keyRune, r: rune(b)}, nil
		}
		return keyEvent{kind: keyUnknown}, nil
	}
}

func readEscapeSequence(file *os.File) (keyEvent, error) {
	fd := int(file.Fd())
	if !waitReadable(fd, 20*time.Millisecond) {
		return keyEvent{kind: keyEscape}, nil
	}
	buf := make([]byte, 1)
	if _, err := file.Read(buf); err != nil {
		return keyEvent{}, err
	}
	seq := []byte{buf[0]}
	for len(seq) < 8 && waitReadable(fd, 2*time.Millisecond) {
		if _, err := file.Read(buf); err != nil {
			return keyEvent{}, err
		}
		seq = append(seq, buf[0])
	}
	switch string(seq) {
	case "[A":
		return keyEvent{kind: keyUp}, nil
	case "[B":
		return keyEvent{kind: keyDown}, nil
	case "[C":
		return keyEvent{kind: keyRight}, nil
	case "[D":
		return keyEvent{kind: keyLeft}, nil
	case "[1;2A":
		return keyEvent{kind: keyShiftUp}, nil
	case "[1;2B":
		return keyEvent{kind: keyShiftDown}, nil
	case "[3~":
		return keyEvent{kind: keyDelete}, nil
	default:
		return keyEvent{kind: keyUnknown}, nil
	}
}

