+		return literalNode{value: value}, nil
+	case tokenIdent:
+		p.next()
+		if p.token.kind == tokenLParen {
+			args, err := p.parseCallArgs(tok.pos)
+			if err != nil {
+				return nil, err
+			}
+			return callNode{name: tok.text, args: args}, nil
+		}
+		return variableNode{name: tok.text}, nil
+	case tokenLBracket:
