package main

import (
	"fmt"
	"os/user"
	"strconv"
	"strings"
	"syscall"
	"time"
)

type statusProgram struct {
	source string
	root   statusNode
}

func compile(source string) (*statusProgram, error) {
	lex := newLexer(source)
	parser := &statusParser{
		source: source,
		lex:    lex,
		token:  lex.next(),
	}
	root, err := parser.parseExpr()
	if err != nil {
		return nil, err
	}
	if parser.token.kind != tokenEOF {
		return nil, parser.unexpected(parser.token)
	}
	return &statusProgram{source: source, root: root}, nil
}

func (p *statusProgram) render(current *entry, files []entry) string {
	if p == nil || current == nil {
		return ""
	}
	out, err := p.root.eval(statusContext{current: current, files: files})
	if err != nil {
		return ""
	}
	return toString(out)
}

type statusContext struct {
	current *entry
	files   []entry
}

type statusNode interface {
	eval(statusContext) (any, error)
}

type literalNode struct {
	value any
}

func (n literalNode) eval(statusContext) (any, error) { return n.value, nil }

type arrayNode struct {
	items []statusNode
}

func (n arrayNode) eval(ctx statusContext) (any, error) {
	out := make([]any, 0, len(n.items))
	for _, item := range n.items {
		value, err := item.eval(ctx)
		if err != nil {
			return nil, err
		}
		out = append(out, value)
	}
	return out, nil
}

type variableNode struct {
	name string
}

func (n variableNode) eval(ctx statusContext) (any, error) {
	switch n.name {
	case "current_file":
		return ctx.current, nil
	case "files":
		out := make([]any, 0, len(ctx.files))
		for i := range ctx.files {
			out = append(out, &ctx.files[i])
		}
		return out, nil
	default:
		return nil, fmt.Errorf("unknown variable %q", n.name)
	}
}

type callNode struct {
	name string
	args []statusNode
}

func (n callNode) eval(ctx statusContext) (any, error) {
	args := make([]any, 0, len(n.args))
	for _, arg := range n.args {
		value, err := arg.eval(ctx)
		if err != nil {
			return nil, err
		}
		args = append(args, value)
	}
	return evalStatusFunction(n.name, nil, args, ctx)
}

type pipeNode struct {
	left statusNode
	name string
	args []statusNode
}

func (n pipeNode) eval(ctx statusContext) (any, error) {
	left, err := n.left.eval(ctx)
	if err != nil {
		return nil, err
	}
	args := make([]any, 0, len(n.args))
	for _, arg := range n.args {
		value, err := arg.eval(ctx)
		if err != nil {
			return nil, err
		}
		args = append(args, value)
	}
	return evalStatusFunction(n.name, left, args, ctx)
}

func evalStatusFunction(name string, piped any, args []any, ctx statusContext) (any, error) {
	callArgs := make([]any, 0, len(args)+1)
	if piped != nil {
		callArgs = append(callArgs, piped)
	}
	callArgs = append(callArgs, args...)
	switch name {
	case "Sprintf":
		if len(callArgs) == 0 {
			return "", nil
		}
		format := toString(callArgs[0])
		return fmt.Sprintf(format, stringifyArgs(callArgs[1:])...), nil
	case "PadLeft":
		if len(callArgs) < 2 {
			return "", nil
		}
		return padLeft(toString(callArgs[0]), toInt(callArgs[1])), nil
	case "PadRight":
		if len(callArgs) < 2 {
			return "", nil
		}
		return padRight(toString(callArgs[0]), toInt(callArgs[1])), nil
	case "join":
		if len(callArgs) < 2 {
			return "", nil
		}
		parts := toSlice(callArgs[0])
		sep := toString(callArgs[1])
		text := make([]string, 0, len(parts))
		for _, part := range parts {
			text = append(text, toString(part))
		}
		return strings.Join(text, sep), nil
	case "Size":
		if ctx.current == nil {
			return "", nil
		}
		return humanSize(ctx.current.size), nil
	case "Mode":
		if ctx.current == nil {
			return "", nil
		}
		return ctx.current.mode.String(), nil
	case "ModTime":
		if ctx.current == nil {
			return "", nil
		}
		return ctx.current.modTime.Format("Jan _2 15:04"), nil
	case "Owner":
		if ctx.current == nil {
			return "", nil
		}
		return formatOwner(ctx.current), nil
	default:
		return nil, fmt.Errorf("unknown function %q", name)
	}
}

func stringifyArgs(args []any) []any {
	out := make([]any, 0, len(args))
	for _, arg := range args {
		out = append(out, toString(arg))
	}
	return out
}

func padLeft(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return strings.Repeat(" ", n-len(s)) + s
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func toInt(value any) int {
	switch v := value.(type) {
	case int:
		return v
	case int64:
		return int(v)
	case float64:
		return int(v)
	case string:
		n, _ := strconv.Atoi(v)
		return n
	default:
		return 0
	}
}

func toSlice(value any) []any {
	switch v := value.(type) {
	case []any:
		return v
	default:
		return nil
	}
}

func toString(value any) string {
	switch v := value.(type) {
	case nil:
		return ""
	case string:
		return v
	case int:
		return strconv.Itoa(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	case time.Time:
		return v.Format(time.RFC3339)
	case *entry:
		if v == nil {
			return ""
		}
		return v.name
	default:
		return fmt.Sprint(v)
	}
}

func humanSize(size int64) string {
	units := []string{"B", "KB", "MB", "GB", "TB"}
	value := float64(size)
	unit := 0
	for value >= 1024 && unit < len(units)-1 {
		value /= 1024
		unit++
	}
	if unit == 0 {
		return fmt.Sprintf("%dB", size)
	}
	return fmt.Sprintf("%.1f%s", value, units[unit])
}

func formatOwner(ent *entry) string {
	if ent == nil || ent.stat == nil {
		return ""
	}
	uid := strconv.FormatUint(uint64(ent.stat.Uid), 10)
	gid := strconv.FormatUint(uint64(ent.stat.Gid), 10)
	userName := uid
	groupName := gid
	if u, err := user.LookupId(uid); err == nil && u.Username != "" {
		userName = u.Username
	}
	if g, err := user.LookupGroupId(gid); err == nil && g.Name != "" {
		groupName = g.Name
	}
	return userName + " " + groupName
}

type tokenKind int

const (
	tokenEOF tokenKind = iota
	tokenIdent
	tokenString
	tokenNumber
	tokenLParen
	tokenRParen
	tokenLBracket
	tokenRBracket
	tokenComma
	tokenPipe
)

type token struct {
	kind tokenKind
	text string
	pos  int
}

type lexer struct {
	source string
	pos    int
}

func newLexer(source string) *lexer {
	return &lexer{source: source}
}

func (l *lexer) next() token {
	for l.pos < len(l.source) {
		switch l.source[l.pos] {
		case ' ', '\t', '\n', '\r':
			l.pos++
		default:
			goto scan
		}
	}
	return token{kind: tokenEOF, pos: len(l.source)}

scan:
	start := l.pos
	switch ch := l.source[l.pos]; ch {
	case '(':
		l.pos++
		return token{kind: tokenLParen, text: "(", pos: start}
	case ')':
		l.pos++
		return token{kind: tokenRParen, text: ")", pos: start}
	case '[':
		l.pos++
		return token{kind: tokenLBracket, text: "[", pos: start}
	case ']':
		l.pos++
		return token{kind: tokenRBracket, text: "]", pos: start}
	case ',':
		l.pos++
		return token{kind: tokenComma, text: ",", pos: start}
	case '|':
		l.pos++
		return token{kind: tokenPipe, text: "|", pos: start}
	case '"':
		l.pos++
		var builder strings.Builder
		for l.pos < len(l.source) {
			c := l.source[l.pos]
			if c == '"' {
				l.pos++
				return token{kind: tokenString, text: builder.String(), pos: start}
			}
			if c == '\\' && l.pos+1 < len(l.source) {
				l.pos++
				builder.WriteByte(l.source[l.pos])
				l.pos++
				continue
			}
			builder.WriteByte(c)
			l.pos++
		}
		return token{kind: tokenEOF, pos: len(l.source)}
	default:
		if isIdentStart(ch) {
			l.pos++
			for l.pos < len(l.source) && isIdentPart(l.source[l.pos]) {
				l.pos++
			}
			return token{kind: tokenIdent, text: l.source[start:l.pos], pos: start}
		}
		if ch >= '0' && ch <= '9' {
			l.pos++
			for l.pos < len(l.source) && l.source[l.pos] >= '0' && l.source[l.pos] <= '9' {
				l.pos++
			}
			return token{kind: tokenNumber, text: l.source[start:l.pos], pos: start}
		}
		l.pos++
		return token{kind: tokenEOF, pos: start}
	}
}

func isIdentStart(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || b == '_'
}

func isIdentPart(b byte) bool {
	return isIdentStart(b) || (b >= '0' && b <= '9')
}

type statusParser struct {
	source string
	lex    *lexer
	token  token
}

func (p *statusParser) next() {
	p.token = p.lex.next()
}

func (p *statusParser) parseExpr() (statusNode, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for p.token.kind == tokenPipe {
		p.next()
		if p.token.kind != tokenIdent {
			return nil, p.unexpected(p.token)
		}
		name := p.token.text
		pos := p.token.pos
		p.next()
		args, err := p.parseCallArgs(pos)
		if err != nil {
			return nil, err
		}
		left = pipeNode{left: left, name: name, args: args}
	}
	return left, nil
}

func (p *statusParser) parsePrimary() (statusNode, error) {
	tok := p.token
	switch tok.kind {
	case tokenString:
		p.next()
		return literalNode{value: tok.text}, nil
	case tokenNumber:
		p.next()
		value, _ := strconv.Atoi(tok.text)
		return literalNode{value: value}, nil
	case tokenIdent:
		p.next()
		if p.token.kind == tokenLParen {
			args, err := p.parseCallArgs(tok.pos)
			if err != nil {
				return nil, err
			}
			return callNode{name: tok.text, args: args}, nil
		}
		return variableNode{name: tok.text}, nil
	case tokenLBracket:
		p.next()
		items := []statusNode{}
		for p.token.kind != tokenRBracket {
			if p.token.kind == tokenEOF {
				return nil, p.unexpected(p.token)
			}
			item, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			items = append(items, item)
			if p.token.kind == tokenComma {
				p.next()
				continue
			}
			if p.token.kind != tokenRBracket {
				return nil, p.unexpected(p.token)
			}
		}
		p.next()
		return arrayNode{items: items}, nil
	default:
		return nil, p.unexpected(tok)
	}
}

func (p *statusParser) parseCallArgs(pos int) ([]statusNode, error) {
	if p.token.kind != tokenLParen {
		return nil, p.unexpected(p.token)
	}
	p.next()
	args := []statusNode{}
	for p.token.kind != tokenRParen {
		if p.token.kind == tokenEOF {
			return nil, p.unexpected(p.token)
		}
		arg, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, arg)
		if p.token.kind == tokenComma {
			p.next()
			continue
		}
		if p.token.kind != tokenRParen {
			return nil, p.unexpected(p.token)
		}
	}
	p.next()
	return args, nil
}

func (p *statusParser) unexpected(tok token) error {
	label := tok.text
	if tok.kind == tokenEOF {
		label = "EOF"
	}
	return parseError{source: p.source, pos: tok.pos + 1, label: label}
}

type parseError struct {
	source string
	pos    int
	label  string
}

func (e parseError) Error() string {
	return fmt.Sprintf("unexpected token %s (1:%d)\n | %s\n | %s^", e.label, e.pos, e.source, strings.Repeat(".", max(e.pos-1, 0)))
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func statOwner(info any) *syscall.Stat_t {
	switch v := info.(type) {
	case *syscall.Stat_t:
		return v
	default:
		return nil
	}
}

