/workspace/main.go.content:
package main

import (
	"bufio"
	"encoding/base64"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
)

const (
	version = "v1.13.0"
)

const helpText = `
  walk v1.13.0

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode
`

type config struct {
	path       string
	icons      bool
	dirOnly    bool
	hideHidden bool
	preview    bool
	withBorder bool
	fuzzy      bool
	action     string
}

type entry struct {
	name      string
	path      string
	display   string
	isDir     bool
	isSymlink bool
	targetDir bool
	mode      os.FileMode
	size      int64
	modTime   time.Time
	stat      *syscall.Stat_t
}

type pendingDelete struct {
	entry    entry
	deadline time.Time
}

type app struct {
	tty             *os.File
	term            *terminal
	cfg             config
	status          *statusProgram
	openWith        map[string]string
	removeCmd       string
	currentPath     string
	entries         []entry
	selection       int
	preferredName   string
	errorMessage    string
	showHidden      bool
	fuzzy           bool
	query           string
	preview         bool
	help            bool
	inAltScreen     bool
	lastRenderLines int
	lastMessage     string
	deleteConfirm   string
	pending         *pendingDelete
}

func main() {
	var status *statusProgram
	if source := os.Getenv("WALK_STATUS_BAR"); source != "" {
		compiled, err := compile(source)
		if err != nil {
			panic(err)
		}
		status = compiled
	}

	cfg := parseArgs(os.Args[1:])
	switch cfg.action {
	case "help":
		fmt.Fprint(os.Stderr, helpText)
		os.Exit(1)
	case "version":
		fmt.Println(version)
		return
	}

	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		panic(fmt.Errorf("could not open a new TTY: %w", err))
	}
	defer tty.Close()

	term, err := newTerminal(tty)
	if err != nil {
		panic(fmt.Errorf("could not open a new TTY: %w", err))
	}

	startPath := cfg.path
	if startPath == "" {
		startPath, err = os.Getwd()
		if err != nil {
			panic(err)
		}
	}
	startPath, err = filepath.Abs(startPath)
	if err != nil {
		panic(err)
	}

	a := &app{
		tty:         tty,
		term:        term,
		cfg:         cfg,
		status:      status,
		openWith:    parseOpenWith(os.Getenv("WALK_OPEN_WITH")),
		removeCmd:   os.Getenv("WALK_REMOVE_CMD"),
		currentPath: startPath,
		showHidden:  !cfg.hideHidden,
		fuzzy:       cfg.fuzzy,
		preview:     cfg.preview,
	}
	a.refresh()

	exitCode, outPath := a.run()
	if exitCode == 0 {
		fmt.Println(outPath)
	}
	os.Exit(exitCode)
}

func parseArgs(args []string) config {
	cfg := config{}
	for _, arg := range args {
		switch arg {
		case "-h", "--help":
			if cfg.action == "" {
				cfg.action = "help"
			}
		case "-v", "--version":
			if cfg.action == "" {
				cfg.action = "version"
			}
		case "--icons":
			cfg.icons = true
		case "--dir-only":
			cfg.dirOnly = true
		case "--hide-hidden":
			cfg.hideHidden = true
		case "--preview":
			cfg.preview = true
		case "--with-border":
			cfg.withBorder = true
		case "--fuzzy":
			cfg.fuzzy = true
		default:
			if cfg.path == "" {
				cfg.path = arg
			}
		}
	}
	return cfg
}

func parseOpenWith(value string) map[string]string {
	if value == "" {
		return nil
	}
	parts := strings.FieldsFunc(value, func(r rune) bool {
		return r == ',' || r == ';' || r == '\n'
	})
	out := make(map[string]string)
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		pieces := strings.SplitN(part, "=", 2)
		if len(pieces) != 2 {
			pieces = strings.SplitN(part, ":", 2)
		}
		if len(pieces) != 2 {
			continue
		}
		ext := strings.TrimSpace(pieces[0])
		cmd := strings.TrimSpace(pieces[1])
		if ext == "" || cmd == "" {
			continue
		}
		if !strings.HasPrefix(ext, ".") {
			ext = "." + ext
		}
		out[strings.ToLower(ext)] = cmd
	}
	return out
}

func (a *app) run() (int, string) {
	if err := a.term.enableRaw(); err != nil {
		panic(err)
	}
	defer a.term.disableRaw()

	fmt.Fprint(a.tty, "\x1b]11;?\x1b\\\x1b[6n")
	fmt.Fprint(a.tty, "\x1b[?25l\x1b[?2004h")
	if a.preview {
		a.enterAltScreen()
	}
	a.render()

	keyCh := make(chan keyEvent, 1)
	errCh := make(chan error, 1)
	go func() {
		for {
			ev, err := readKey(a.tty)
			if err != nil {
				errCh <- err
				return
			}
			keyCh <- ev
		}
	}()

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case err := <-errCh:
			if err != nil {
				a.shutdown()
				return 2, ""
			}
		case <-ticker.C:
			if a.advancePendingDelete() {
				a.render()
			}
		case ev := <-keyCh:
			code, out, redraw := a.handleKey(ev)
			if redraw {
				a.render()
			}
			if code >= 0 {
				a.shutdown()
				return code, out
			}
		}
	}
}

func (a *app) handleKey(ev keyEvent) (int, string, bool) {
	switch ev.kind {
	case keyCtrlC:
		return 2, "", false
	case keyEscape:
		return 0, a.currentPath, false
	case keyEnter:
		return -1, "", a.enterSelection()
	case keyBackspace:
		if a.fuzzy && a.query != "" {
			a.query = trimLastRune(a.query)
			a.refresh()
			return -1, "", true
		}
		if a.fuzzy && a.query == "" {
			a.fuzzy = false
			a.refresh()
			return -1, "", true
		}
		a.goParent()
		return -1, "", true
	case keyUp:
		return -1, "", a.moveSelection(-1)
	case keyDown:
		return -1, "", a.moveSelection(1)
	case keyShiftUp:
		return -1, "", a.jumpSelection(0)
	case keyShiftDown:
		return -1, "", a.jumpSelection(len(a.entries)-1)
	case keyDelete:
		return -1, "", a.startDelete(true)
	case keyLeft, keyRight:
		return -1, "", false
	case keyRune:
		switch ev.r {
		case 'q':
			return 0, a.currentPath, false
		case '?':
			a.help = !a.help
			return -1, "", true
		case '.':
			a.showHidden = !a.showHidden
			a.clearTransientState()
			a.refresh()
			return -1, "", true
		case ' ':
			a.preview = !a.preview
			if a.preview {
				a.enterAltScreen()
			} else {
				a.leaveAltScreen()
			}
			return -1, "", true
		case '/':
			a.fuzzy = true
			return -1, "", true
		case 'j':
			return -1, "", a.moveSelection(1)
		case 'k':
			return -1, "", a.moveSelection(-1)
		case 'h', 'l':
			return -1, "", false
		case 'y':
			a.copySelection()
			return -1, "", true
		case 'u':
			if a.pending != nil {
				a.pending = nil
				a.lastMessage = ""
				a.refresh()
				return -1, "", true
			}
			return -1, "", false
		case 'd':
			return -1, "", a.startDelete(false)
		default:
			if a.fuzzy && ev.r >= 32 {
				a.query += string(ev.r)
				a.refresh()
				return -1, "", true
			}
		}
	}
	return -1, "", false
}

func (a *app) clearTransientState() {
	a.help = false
	a.deleteConfirm = ""
}

func (a *app) moveSelection(delta int) bool {
	if len(a.entries) == 0 {
		return false
	}
	a.clearTransientState()
	a.lastMessage = ""
	a.selection = (a.selection + delta + len(a.entries)) % len(a.entries)
	return true
}

func (a *app) jumpSelection(index int) bool {
	if len(a.entries) == 0 {
		return false
	}
	a.clearTransientState()
	a.lastMessage = ""
	if index < 0 {
		index = 0
	}
	if index >= len(a.entries) {
		index = len(a.entries) - 1
	}
	a.selection = index
	return true
}

func (a *app) currentEntry() *entry {
	if len(a.entries) == 0 || a.selection < 0 || a.selection >= len(a.entries) {
		return nil
	}
	return &a.entries[a.selection]
}

func (a *app) enterSelection() bool {
	a.clearTransientState()
	current := a.currentEntry()
	if current == nil {
		return false
	}
	if current.isDir || current.targetDir {
		a.currentPath = current.path
		a.preferredName = ""
		a.refresh()
		return true
	}
	command := a.commandFor(current)
	if command == "" {
		return false
	}
	a.suspendForCommand()
	cmd := exec.Command("sh", "-c", command+" \"$1\"", "walk-open", current.path)
	cmd.Stdin = a.tty
	cmd.Stdout = a.tty
	cmd.Stderr = a.tty
	_ = cmd.Run()
	a.resumeAfterCommand()
	return true
}

func (a *app) commandFor(ent *entry) string {
	if ent == nil {
		return ""
	}
	if a.openWith != nil {
		if cmd := a.openWith[strings.ToLower(filepath.Ext(ent.name))]; cmd != "" {
			return cmd
		}
	}
	if value := os.Getenv("WALK_EDITOR"); value != "" {
		return value
	}
	return os.Getenv("EDITOR")
}

func (a *app) goParent() {
	a.clearTransientState()
	a.lastMessage = ""
	if a.currentPath == "/" {
		return
	}
	name := filepath.Base(a.currentPath)
	parent := filepath.Dir(a.currentPath)
	if parent == "." || parent == "" {
		parent = "/"
	}
	a.currentPath = parent
	a.preferredName = name
	a.refresh()
}

func (a *app) copySelection() {
	current := a.currentEntry()
	if current == nil {
		return
	}
	encoded := base64.StdEncoding.EncodeToString([]byte(current.path))
	fmt.Fprintf(a.tty, "\x1b]52;c;%s\x07", encoded)
	a.lastMessage = "copied: " + current.path
}

func (a *app) startDelete(immediate bool) bool {
	current := a.currentEntry()
	if current == nil {
		return false
	}
	if immediate {
		a.pending = &pendingDelete{entry: *current, deadline: time.Now().Add(5 * time.Second)}
		a.deleteConfirm = ""
		a.lastMessage = ""
		a.refresh()
		return true
	}
	if a.deleteConfirm == current.path {
		a.pending = &pendingDelete{entry: *current, deadline: time.Now().Add(5 * time.Second)}
		a.deleteConfirm = ""
		a.lastMessage = ""
		a.refresh()
		return true
	}
	a.deleteConfirm = current.path
	return true
}

func (a *app) advancePendingDelete() bool {
	if a.pending == nil {
		return false
	}
	remaining := int(time.Until(a.pending.deadline).Seconds())
	if remaining < 0 {
		if err := a.performDelete(a.pending.entry); err != nil {
			a.lastMessage = err.Error()
		}
		a.pending = nil
		a.refresh()
		return true
	}
	newMessage := fmt.Sprintf("%s deleted. (u)ndo %d", a.pending.entry.name, remaining)
	if newMessage != a.lastMessage {
		a.lastMessage = newMessage
		return true
	}
	return false
}

func (a *app) performDelete(ent entry) error {
	if a.removeCmd != "" {
		cmd := exec.Command("sh", "-c", a.removeCmd+" \"$1\"", "walk-rm", ent.path)
		return cmd.Run()
	}
	if ent.isDir && !ent.isSymlink {
		return os.RemoveAll(ent.path)
	}
	return os.Remove(ent.path)
}

func (a *app) refresh() {
	a.errorMessage = ""
	a.entries = nil

	list, err := os.ReadDir(a.currentPath)
	if err != nil {
		a.errorMessage = err.Error()
		a.selection = 0
		return
	}

	entries := make([]entry, 0, len(list))
	for _, item := range list {
		name := item.Name()
		if !a.showHidden && strings.HasPrefix(name, ".") {
			continue
		}
		ent, ok := a.buildEntry(item)
		if !ok {
			continue
		}
		if a.pending != nil && ent.path == a.pending.entry.path {
			continue
		}
		if a.cfg.dirOnly && !(ent.isDir || ent.targetDir) {
			continue
		}
		if a.query != "" && !fuzzyMatch(name, a.query) {
			continue
		}
		entries = append(entries, ent)
	}

	sort.Slice(entries, func(i, j int) bool {
		return entries[i].name < entries[j].name
	})

	a.entries = entries
	a.selection = 0
	if a.preferredName != "" {
		for i := range a.entries {
			if a.entries[i].name == a.preferredName {
				a.selection = i
				break
			}
		}
	}
	a.preferredName = ""
}

func (a *app) buildEntry(item os.DirEntry) (entry, bool) {
	fullPath := filepath.Join(a.currentPath, item.Name())
	info, err := item.Info()
	if err != nil {
		return entry{}, false
	}
	ent := entry{
		name:      item.Name(),
		path:      fullPath,
		isDir:     item.IsDir(),
		isSymlink: item.Type()&os.ModeSymlink != 0,
		mode:      info.Mode(),
		size:      info.Size(),
		modTime:   info.ModTime(),
		display:   item.Name(),
	}
	if ent.isDir {
		ent.display += "/"
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); ok {
		ent.stat = stat
	}
	if ent.isSymlink {
		if targetInfo, err := os.Stat(fullPath); err == nil && targetInfo.IsDir() {
			ent.targetDir = true
		}
	}
	return ent, true
}

func fuzzyMatch(text, query string) bool {
	text = strings.ToLower(text)
	query = strings.ToLower(query)
	if query == "" {
		return true
	}
	index := 0
	for _, r := range text {
		if index < len(query) && byte(r) == query[index] {
			index++
			if index == len(query) {
				return true
			}
		}
	}
	return false
}

func (a *app) render() {
	lines := a.renderLines()
	if a.inAltScreen {
		fmt.Fprint(a.tty, "\x1b[H")
	} else if a.lastRenderLines > 0 {
		fmt.Fprintf(a.tty, "\x1b[%dA", a.lastRenderLines-1)
	}
	for i, line := range lines {
		if i > 0 {
			fmt.Fprint(a.tty, "\r\n")
		}
		fmt.Fprint(a.tty, line)
		fmt.Fprint(a.tty, "\x1b[K")
	}
	if len(lines) < a.lastRenderLines {
		for i := len(lines); i < a.lastRenderLines; i++ {
			fmt.Fprint(a.tty, "\r\n\x1b[K")
		}
	}
	a.lastRenderLines = len(lines)
}

func (a *app) renderLines() []string {
	if a.help {
		lines := []string{
			"help",
			"",
			"    arrows, hjkl  Move cursor",
			"    enter         Enter directory",
			"    backspace     Exit directory",
			"    space         Toggle preview",
			"    esc, q        Exit with cd",
			"    ctrl+c        Exit without cd",
			"    /             Fuzzy search",
			"    d, delete     Delete file or dir",
			"    y             Copy to clipboard",
			"    .             Hide hidden files",
			"    ?             Show help",
			"",
			"",
		}
		return lines
	}
	if a.preview {
		return a.renderPreview()
	}
	return a.renderList()
}

func (a *app) renderList() []string {
	lines := []string{a.headerPath()}
	switch {
	case a.errorMessage != "":
		lines = append(lines, boxLines(a.errorMessage)...)
	case len(a.entries) == 0:
		lines = append(lines, boxLines("No files")...)
	default:
		for i, ent := range a.entries {
			lines = append(lines, a.decorateLine(ent.display, ent, i == a.selection))
		}
	}
	if message := a.bottomLine(); message != "" {
		lines = append(lines, message)
	} else if status := a.statusLine(); status != "" {
		lines = append(lines, status)
	}
	return lines
}

func (a *app) renderPreview() []string {
	_, cols := terminalSize(a.tty)
	if cols < 40 {
		return a.renderList()
	}
	leftWidth := cols / 2
	sep := "  "
	if a.cfg.withBorder {
		sep = " │ "
	}
	rightWidth := cols - leftWidth - len(sep)
	if rightWidth < 1 {
		rightWidth = 1
	}

	left := []string{"/" + filepath.Base(a.currentPath)}
	switch {
	case a.errorMessage != "":
		left = append(left, boxLines(a.errorMessage)...)
	case len(a.entries) == 0:
		left = append(left, boxLines("No files")...)
	default:
		for i, ent := range a.entries {
			left = append(left, a.decorateLine(trimToWidth(ent.display, leftWidth), ent, i == a.selection))
		}
	}

	right := a.previewLines()
	count := len(left)
	if len(right) > count {
		count = len(right)
	}
	lines := make([]string, 0, count)
	for i := 0; i < count; i++ {
		l := ""
		r := ""
		if i < len(left) {
			l = left[i]
		}
		if i < len(right) {
			r = right[i]
		}
		lines = append(lines, padRight(trimToWidth(l, leftWidth), leftWidth)+sep+trimToWidth(r, rightWidth))
	}
	return lines
}

func (a *app) previewLines() []string {
	current := a.currentEntry()
	if current == nil {
		return []string{""}
	}
	lines := []string{current.name}
	if current.isDir || current.targetDir {
		children, err := os.ReadDir(current.path)
		if err != nil {
			return append(lines, boxLines(err.Error())...)
		}
		names := make([]string, 0, len(children))
		for _, child := range children {
			name := child.Name()
			if !a.showHidden && strings.HasPrefix(name, ".") {
				continue
			}
			if child.IsDir() {
				name += "/"
			}
			names = append(names, name)
		}
		sort.Strings(names)
		return append(lines, names...)
	}
	file, err := os.Open(current.path)
	if err != nil {
		return append(lines, boxLines(err.Error())...)
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
		if len(lines) > 200 {
			break
		}
	}
	return lines
}

func (a *app) headerPath() string {
	if a.fuzzy && a.query != "" {
		return a.currentPath + "/" + a.query
	}
	return a.currentPath
}

func (a *app) statusLine() string {
	return a.status.render(a.currentEntry(), a.entries)
}

func (a *app) bottomLine() string {
	if a.lastMessage != "" {
		return a.lastMessage
	}
	return ""
}

func (a *app) decorateLine(text string, ent entry, selected bool) string {
	if !selected {
		return text
	}
	color := "7"
	if os.Getenv("WALK_MAIN_COLOR") != "" {
		color = colorForName(os.Getenv("WALK_MAIN_COLOR"))
	}
	if a.deleteConfirm == ent.path {
		return "\x1b[31m" + text + "\x1b[0m"
	}
	return "\x1b[" + color + "m" + text + "\x1b[0m"
}

func colorForName(name string) string {
	switch strings.ToLower(name) {
	case "black":
		return "30"
	case "red":
		return "31"
	case "green":
		return "32"
	case "yellow":
		return "33"
	case "blue":
		return "34"
	case "magenta":
		return "35"
	case "cyan":
		return "36"
	case "white":
		return "37"
	default:
		return "7"
	}
}

func boxLines(message string) []string {
	width := len(message) + 2
	return []string{
		"╭" + strings.Repeat("─", width) + "╮",
		"│ " + message + " │",
		"╰" + strings.Repeat("─", width) + "╯",
	}
}

func trimToWidth(s string, width int) string {
	if width <= 0 {
		return ""
	}
	if len(s) <= width {
		return s
	}
	return s[:width]
}

func trimLastRune(s string) string {
	if s == "" {
		return s
	}
	_, size := utf8LastRuneInString(s)
	return s[:len(s)-size]
}

func utf8LastRuneInString(s string) (rune, int) {
	for i := len(s) - 1; i >= 0; i-- {
		if s[i]&0xC0 != 0x80 {
			r := rune(s[i])
			size := 1
			if r >= 0xC0 {
				r, size = utf8DecodeRuneInString(s[i:])
			}
			return r, size
		}
	}
	return 0, 0
}

func utf8DecodeRuneInString(s string) (rune, int) {
	for size := 1; size <= len(s); size++ {
		r := []rune(s[:size])
		if len(r) == 1 {
			return r[0], len(string(r[0]))
		}
	}
	return rune(s[0]), 1
}

func (a *app) suspendForCommand() {
	if a.preview {
		a.leaveAltScreen()
	}
	fmt.Fprint(a.tty, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
	_ = a.term.disableRaw()
}

func (a *app) resumeAfterCommand() {
	_ = a.term.enableRaw()
	fmt.Fprint(a.tty, "\x1b[?25l\x1b[?2004h")
	if a.preview {
		a.enterAltScreen()
	}
	a.render()
}

func (a *app) enterAltScreen() {
	if a.inAltScreen {
		return
	}
	fmt.Fprint(a.tty, "\x1b[?1049h\x1b[2J\x1b[H")
	a.inAltScreen = true
}

func (a *app) leaveAltScreen() {
	if !a.inAltScreen {
		return
	}
	fmt.Fprint(a.tty, "\x1b[?1049l\x1b[?25h")
	a.inAltScreen = false
	a.lastRenderLines = 0
	fmt.Fprint(a.tty, "\x1b[?25l")
}

func (a *app) shutdown() {
	if a.inAltScreen {
		fmt.Fprint(a.tty, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l\x1b[?1049l")
	} else {
		fmt.Fprint(a.tty, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
	}
}

