		return token{kind: tokenEOF, pos: start}
	}
}

func isIdentStart(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z') || b == '_'
}

func isIdentPart(b byte) bool {
	return isIdentStart(b) || (b >= '0' && b <= '9')
}

type statusParser struct {
	source string
	lex    *lexer
	token  token
}

func (p *statusParser) next() {
	p.token = p.lex.next()
}

func (p *statusParser) parseExpr() (statusNode, error) {
	left, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for p.token.kind == tokenPipe {
		p.next()
		if p.token.kind != tokenIdent {
			return nil, p.unexpected(p.token)
		}
		name := p.token.text
		p.next()
		args, err := p.parseCallArgs()
		if err != nil {
			return nil, err
		}
		left = pipeNode{left: left, name: name, args: args}
	}
	return left, nil
}

func (p *statusParser) parsePrimary() (statusNode, error) {
	tok := p.token
	switch tok.kind {
	case tokenString:
		p.next()
		return literalNode{value: tok.text}, nil
	case tokenNumber:
		p.next()
		value, _ := strconv.Atoi(tok.text)
		return literalNode{value: value}, nil
	case tokenIdent:
		p.next()
		if p.token.kind == tokenLParen {
			args, err := p.parseCallArgs()
			if err != nil {
				return nil, err
			}
			return callNode{name: tok.text, args: args}, nil
		}
		return variableNode{name: tok.text}, nil
	case tokenLBracket:
		p.next()
		items := []statusNode{}
		for p.token.kind != tokenRBracket {
			if p.token.kind == tokenEOF {
				return nil, p.unexpected(p.token)
			}
			item, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			items = append(items, item)
			if p.token.kind == tokenComma {
				p.next()
				continue
			}
			if p.token.kind != tokenRBracket {
				return nil, p.unexpected(p.token)
			}
		}
		p.next()
		return arrayNode{items: items}, nil
	default:
		return nil, p.unexpected(tok)
	}
}

func (p *statusParser) parseCallArgs() ([]statusNode, error) {
	if p.token.kind != tokenLParen {
		return nil, p.unexpected(p.token)
	}
	p.next()
	args := []statusNode{}
	for p.token.kind != tokenRParen {
		if p.token.kind == tokenEOF {
			return nil, p.unexpected(p.token)
		}
		arg, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, arg)
		if p.token.kind == tokenComma {
			p.next()
			continue
		}
		if p.token.kind != tokenRParen {
			return nil, p.unexpected(p.token)
		}
	}
	p.next()
	return args, nil
}

func (p *statusParser) unexpected(tok token) error {
	label := tok.text
	if tok.kind == tokenEOF {
		label = "EOF"
	}
	return parseError{source: p.source, pos: tok.pos + 1, label: label}
}

type parseError struct {
	source string
	pos    int
	label  string
}

func (e parseError) Error() string {
	return fmt.Sprintf("unexpected token %s (1:%d)\n | %s\n | %s^", e.label, e.pos, e.source, strings.Repeat(".", maxInt(e.pos-1, 0)))
